import {useState} from 'react'
import {UnderlineNav} from '@primer/react'
import {Link} from '@github-ui/react-router'
import {useSearchParams} from '@github-ui/use-navigate'

import {LicensePolicyHeader} from '../LicensePolicyPage/LicensePolicyHeader'
import {LicensePolicyAllowedLicenses} from '../LicensePolicyPage/LicensePolicyAllowedLicenses'
import {LicensePolicyAddDialog} from '../LicensePolicyPage/LicensePolicyAddDialog'
import {LicensePolicyPackageExceptions} from '../LicensePolicyPage/LicensePolicyPackageExceptions'
import type {LicensePolicyResponse} from '../../types/policies'
import type {PackagePolicy} from '../../types/packages'
import {useUserPermissions} from '../../context/UserPermissionsContext'

import styles from '../../routes/LicensePolicy.module.css'

const ALLOWED_LICENSES = 'allowed-licenses'
const PACKAGE_EXCEPTIONS = 'package-exceptions'

interface LicensePolicyPageProps {
  preview: boolean
  pageDescription: string
  licensesDescription: string
  exceptionsDescription: string
  data: LicensePolicyResponse
  enterpriseName?: string
  enterpriseSlug?: string
  addAllowedLicensesMutation?: {
    mutate: (params: {spdxIds: string[]; context: string}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
  deleteAllowedLicensesMutation?: {
    mutate: (params: {spdxIds: string[]; context?: string}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
  deletePackageExceptionsMutation?: {
    mutate: (params: {packages: PackagePolicy[]}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
}

export function LicensePolicyPage({
  preview,
  pageDescription,
  licensesDescription,
  exceptionsDescription,
  data,
  enterpriseName,
  enterpriseSlug,
  addAllowedLicensesMutation,
  deleteAllowedLicensesMutation,
  deletePackageExceptionsMutation,
}: LicensePolicyPageProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [searchParams] = useSearchParams()
  const selectedTab = searchParams.get('tab') || ALLOWED_LICENSES
  const {canManagePolicy} = useUserPermissions()

  return (
    <>
      <LicensePolicyHeader
        title="License Policy"
        description={pageDescription}
        preview={preview}
        enterpriseName={enterpriseName}
        enterpriseSlug={enterpriseSlug}
      />

      {/* Navigation tabs */}
      <UnderlineNav aria-label="License Policy Navigation" className={styles.UnderlineNav}>
        <UnderlineNav.Item
          as={Link}
          to={`?tab=${ALLOWED_LICENSES}`}
          aria-current={selectedTab === ALLOWED_LICENSES ? 'page' : undefined}
        >
          Licenses
        </UnderlineNav.Item>
        <UnderlineNav.Item
          as={Link}
          to={`?tab=${PACKAGE_EXCEPTIONS}`}
          aria-current={selectedTab === PACKAGE_EXCEPTIONS ? 'page' : undefined}
        >
          Exceptions
        </UnderlineNav.Item>
      </UnderlineNav>

      {/* Licenses tab content */}
      {selectedTab === ALLOWED_LICENSES && (
        <>
          <LicensePolicyAllowedLicenses
            aria-label="Allowed licenses management"
            description={licensesDescription}
            licenses={data.allowed}
            datePolicyAdded={data.date_added}
            onAddLicenseClick={addAllowedLicensesMutation && canManagePolicy ? () => setIsDialogOpen(true) : undefined}
            deleteAllowedLicensesMutation={deleteAllowedLicensesMutation}
          />

          {/* Modal dialog for adding new licenses */}
          {addAllowedLicensesMutation && (
            <LicensePolicyAddDialog
              isOpen={isDialogOpen}
              onClose={() => setIsDialogOpen(false)}
              addAllowedLicensesMutation={addAllowedLicensesMutation}
            />
          )}
        </>
      )}

      {/* Exceptions tab content */}
      {selectedTab === PACKAGE_EXCEPTIONS && (
        <LicensePolicyPackageExceptions
          aria-label="Package exceptions management"
          description={exceptionsDescription}
          packages={data.packages}
          deletePackageExceptionsMutation={deletePackageExceptionsMutation}
        />
      )}
    </>
  )
}
