import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'

import {enterpriseLicensePolicyRoute, repositoryLicensePolicyRoute} from '../routes/license-policy-route'
import {deleteLicensesFromEnterprisePolicy, deleteLicensesFromRepositoryPolicy} from '../services/licenses'
import type {
  DeleteLicensesFromEnterprisePolicyPayload,
  DeleteLicensesFromRepositoryPolicyPayload,
} from '../types/licenses'

// Mutation for deleting licenses from the allowed licenses list of an enterprise policy
export function useDeleteAllowedLicensesFromEnterpriseMutation() {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(enterpriseLicensePolicyRoute, 'mainQuery')

  const {business} = useRouteParams(enterpriseLicensePolicyRoute)
  if (!business) {
    throw new Error('Business slug not found in route parameters')
  }

  return useMutation({
    mutationFn: ({spdxIds, context}: {spdxIds: string[]; context?: string}) => {
      const payload: DeleteLicensesFromEnterprisePolicyPayload = {
        enterprise_slug: business,
        spdx_ids: spdxIds,
        ...(context ? {context} : {}),
      }
      // Call service which interacts with the OLC API
      return deleteLicensesFromEnterprisePolicy(payload)
    },
    onSuccess: () => {
      // Refresh the license policy data
      queryClient.invalidateQueries({queryKey})
    },
  })
}

// Mutation for deleting licenses from the allowed licenses list of a repository policy
export function useDeleteAllowedLicensesFromRepositoryMutation() {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(repositoryLicensePolicyRoute, 'mainQuery')

  const {organization, repository} = useRouteParams(repositoryLicensePolicyRoute)
  if (!organization) {
    throw new Error('Organization slug not found in route parameters')
  }
  if (!repository) {
    throw new Error('Repository slug not found in route parameters')
  }

  return useMutation({
    mutationFn: ({spdxIds}: {spdxIds: string[]}) => {
      const payload: DeleteLicensesFromRepositoryPolicyPayload = {
        organization_slug: organization,
        repository_slug: repository,
        spdx_ids: spdxIds,
      }
      // Call service which interacts with the OLC API
      return deleteLicensesFromRepositoryPolicy(payload)
    },
    onSuccess: () => {
      // Refresh the license policy data
      queryClient.invalidateQueries({queryKey})
    },
  })
}
