import {Textarea, Button} from '@primer/react'
import {Dialog, InlineMessage} from '@primer/react/experimental'
import {useState} from 'react'

interface LicensePolicyAddDialogProps {
  isOpen: boolean
  onClose: () => void
  addAllowedLicensesMutation?: {
    mutate: (params: {spdxIds: string[]; context: string; onClose?: () => void}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
}

export function LicensePolicyAddDialog({isOpen, onClose, addAllowedLicensesMutation}: LicensePolicyAddDialogProps) {
  const [newLicenses, setNewLicenses] = useState('')

  // Custom close handler that clears the dialog state
  const handleClose = () => {
    setNewLicenses('') // Clear textarea content
    onClose() // Call parent close handler
  }

  // Handler for updating the new license input value
  const handleLicensesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewLicenses(e.target.value)
    // Reset error state when user starts typing
    if (addAllowedLicensesMutation?.isError) {
      addAllowedLicensesMutation.reset()
    }
  }

  // Handler for adding new licenses to the enterprise policy
  const handleAddLicenses = () => {
    if (!addAllowedLicensesMutation) {
      return
    }

    // Parse new licenses from textarea (one per line, trim whitespace, filter empty lines)
    const parsedLicenseList = newLicenses
      .split('\n')
      .map(license => license.trim())
      .filter(license => license.length > 0)

    addAllowedLicensesMutation.mutate({
      spdxIds: parsedLicenseList,
      context: 'distributed',
      onClose: handleClose,
    })
  }

  if (!isOpen) return null

  return (
    <Dialog title="Add licenses" onClose={handleClose}>
      <div className="tmp-p-3">
        {addAllowedLicensesMutation?.isError && (
          <InlineMessage variant="critical" className="tmp-mb-3">
            <span>
              <strong>Error:</strong>
              <span> {addAllowedLicensesMutation.error?.message || 'Failed to add licenses. Please try again.'}</span>
            </span>
          </InlineMessage>
        )}
        <Textarea
          block
          value={newLicenses}
          onChange={handleLicensesChange}
          rows={4}
          maxLength={5000}
          resize="vertical"
          placeholder="Enter a valid SPDX license identifier on each line"
          aria-label="SPDX license identifiers, one per line"
          data-1p-ignore="true"
          autoComplete="off"
        />
      </div>
      <Dialog.Footer>
        <Button onClick={handleClose}>Cancel</Button>
        <Button
          variant="primary"
          onClick={handleAddLicenses}
          loading={addAllowedLicensesMutation?.isPending}
          disabled={newLicenses.trim().length === 0 || !addAllowedLicensesMutation}
        >
          Add
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}
