import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

import {PolicyLevel, IS_IN_PREVIEW} from '../types/policy-levels'
import {PolicyLevelProvider} from '../context/PolicyLevelContext'
import {UserPermissionsProvider} from '../context/UserPermissionsContext'
import {repositoryLicensePolicyRoute} from './license-policy-route'
import {RepositoryLicensePolicyPage} from '../components/LicensePolicy/RepositoryLicensePolicy'

export function RepositoryLicensePolicy() {
  // Get license policy payload from the route
  const payload = useRouteQuery(repositoryLicensePolicyRoute, 'mainQuery')
  const canManagePolicy = !!payload.data.can_manage_license_policy
  return (
    <PolicyLevelProvider policyLevel={PolicyLevel.Repository}>
      <UserPermissionsProvider canManagePolicy={canManagePolicy}>
        <RepositoryLicensePolicyPage preview={IS_IN_PREVIEW} data={payload.data} />
      </UserPermissionsProvider>
    </PolicyLevelProvider>
  )
}
