import type {PackagePolicy} from './packages'
import type {LicenseEntry} from './licenses'
import {PolicyLevel} from './policy-levels'

// Common data shared across all policy levels
export interface PolicyResponseData {
  allowed: LicenseEntry[]
  packages: PackagePolicy[]
  date_added: string
  can_manage_license_policy?: boolean
}

// Generic license policy response with normalized id field
export interface LicensePolicyResponse extends PolicyResponseData {
  id: number
}

// Combined response types (for backward compatibility)
export interface EnterpriseLicensePolicyResponse extends PolicyResponseData {
  enterprise_id: number
}
export interface OrganizationLicensePolicyResponse extends PolicyResponseData {
  organization_id: number
}
export interface RepositoryLicensePolicyResponse extends PolicyResponseData {
  repository_id: number
  enterprise_name?: string
  enterprise_slug?: string
}

// Utility functions to convert between specific and generic formats
export function toGenericLicensePolicyResponse(
  level: PolicyLevel,
  response: EnterpriseLicensePolicyResponse | OrganizationLicensePolicyResponse | RepositoryLicensePolicyResponse,
): LicensePolicyResponse {
  switch (level) {
    case PolicyLevel.Enterprise: {
      const enterpriseResponse = response as EnterpriseLicensePolicyResponse
      return {
        id: enterpriseResponse.enterprise_id,
        allowed: enterpriseResponse.allowed,
        packages: enterpriseResponse.packages,
        date_added: enterpriseResponse.date_added,
        can_manage_license_policy: enterpriseResponse.can_manage_license_policy,
      }
    }
    case PolicyLevel.Organization: {
      const organizationResponse = response as OrganizationLicensePolicyResponse
      return {
        id: organizationResponse.organization_id,
        allowed: organizationResponse.allowed,
        packages: organizationResponse.packages,
        date_added: organizationResponse.date_added,
        can_manage_license_policy: organizationResponse.can_manage_license_policy,
      }
    }
    case PolicyLevel.Repository: {
      const repositoryResponse = response as RepositoryLicensePolicyResponse
      return {
        id: repositoryResponse.repository_id,
        allowed: repositoryResponse.allowed,
        packages: repositoryResponse.packages,
        date_added: repositoryResponse.date_added,
        can_manage_license_policy: repositoryResponse.can_manage_license_policy,
      }
    }
    default:
      throw new Error(`Unsupported policy level: ${level}`)
  }
}
