import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {TrashIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import {clsx} from 'clsx'

interface BaseListItemProps {
  title: string
  description?: string
  isSelected: boolean
  hasCheckboxes: boolean
  onSelect: () => void
  onDelete?: () => void
}

export function BaseListItem({title, description, isSelected, hasCheckboxes, onSelect, onDelete}: BaseListItemProps) {
  const renderDeleteButton = () => {
    if (!onDelete) return null
    return (
      <IconButton
        data-testid={`delete-button-${title}`}
        onClick={onDelete}
        icon={TrashIcon}
        size="small"
        variant="invisible"
        aria-label={`Delete ${title}`}
      />
    )
  }

  const listItemClassName = clsx({
    'pl-2': !hasCheckboxes,
  })

  return (
    <ListItem
      title={<ListItemTitle value={title} />}
      isSelected={isSelected}
      onSelect={() => onSelect()}
      metadata={<ListItemMetadata>{renderDeleteButton()}</ListItemMetadata>}
      className={listItemClassName}
    >
      <ListItemMainContent>
        {description && <ListItemDescription>{description}</ListItemDescription>}
      </ListItemMainContent>
    </ListItem>
  )
}
