import {BaseListHeader} from '../BaseListView/BaseListHeader'

interface AllowedLicensesHeaderProps {
  description: string
  onAddLicenseClick?: () => void
}

export function AllowedLicensesHeader({description, onAddLicenseClick}: AllowedLicensesHeaderProps) {
  return (
    <BaseListHeader
      title="Allowed Licenses"
      description={description}
      addButtonLabel={onAddLicenseClick ? 'Add licenses' : undefined}
      onAddClick={onAddLicenseClick}
      aria-label="Allowed Licenses"
    />
  )
}
