import {createContext, use, type PropsWithChildren} from 'react'

export interface UserPermissionsContextValue {
  canManagePolicy: boolean
}

const DefaultUserPermissionsContextValue: UserPermissionsContextValue = {
  canManagePolicy: false,
}

const UserPermissionsContext = createContext(DefaultUserPermissionsContextValue)

export function UserPermissionsProvider({children, ...props}: PropsWithChildren<UserPermissionsContextValue>) {
  return <UserPermissionsContext value={props}>{children}</UserPermissionsContext>
}

export function useUserPermissions(): UserPermissionsContextValue {
  const context = use(UserPermissionsContext)
  return context
}
