import React, {createContext, use} from 'react'
import {PolicyLevel} from '../types/policy-levels'

const PolicyLevelContext = createContext<PolicyLevel | undefined>(undefined)

interface PolicyLevelProviderProps {
  children: React.ReactNode
  policyLevel: PolicyLevel
}

export function PolicyLevelProvider({children, policyLevel}: PolicyLevelProviderProps) {
  return <PolicyLevelContext value={policyLevel}>{children}</PolicyLevelContext>
}

export function usePolicyLevel(): PolicyLevel {
  const context = use(PolicyLevelContext)
  if (context === undefined) {
    throw new Error('usePolicyLevel must be used within a PolicyLevelProvider')
  }
  return context
}
