import {useState} from 'react'
import {LawIcon} from '@primer/octicons-react'
import {LicensePolicyDeleteDialog} from '../LicensePolicyPage/LicensePolicyDeleteDialog'
import {BaseList} from '../BaseListView/BaseList'
import {AllowedLicensesListItem} from './AllowedLicensesListItem'
import {AllowedLicensesFilter} from './AllowedLicensesFilter'
import {ItemType, type LicenseEntry} from '../../types/licenses'
import {PolicyLevel} from '../../types/policy-levels'
import {usePolicyLevel} from '../../context/PolicyLevelContext'
import {useUserPermissions} from '../../context/UserPermissionsContext'

interface AllowedLicensesListProps {
  licenses: LicenseEntry[]
  datePolicyAdded: string
  deleteAllowedLicensesMutation?: {
    mutate: (params: {spdxIds: string[]; context?: string}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
}

export function AllowedLicensesList({
  licenses,
  datePolicyAdded,
  deleteAllowedLicensesMutation,
}: AllowedLicensesListProps) {
  const level = usePolicyLevel()
  const {canManagePolicy} = useUserPermissions()

  const [itemsToDelete, setItemsToDelete] = useState<{spdxIds: string[]; isBulk: boolean} | null>(null)
  const [clearSelectionCallback, setClearSelectionCallback] = useState<(() => void) | null>(null)

  // Filter function for license strings
  const filterLicenses = (license: LicenseEntry, filterText: string): boolean => {
    return license.spdx_id.toLowerCase().includes(filterText.toLowerCase())
  }

  // Sort function for license strings (alphabetical, case-insensitive)
  const sortLicenses = (a: LicenseEntry, b: LicenseEntry): number => {
    return a.spdx_id.toLowerCase().localeCompare(b.spdx_id.toLowerCase())
  }

  // Render function for each license item
  const renderLicenseItem = (
    license: LicenseEntry,
    _index: number,
    isSelected: boolean,
    onSelect: () => void,
    itemKey: string,
  ) => (
    <AllowedLicensesListItem
      key={itemKey}
      spdxID={license.spdx_id}
      spdxName={license.spdx_id} // TODO: Use actual SPDX full name. Tmp using SPDX ID as name.
      dateAdded={license.added_at || datePolicyAdded}
      isSelected={isSelected}
      onSelect={onSelect}
      onDelete={canDelete(license) ? () => onDelete(license.spdx_id) : undefined}
      hasCheckboxes={!!onBulkDelete}
    />
  )

  // Render function for search and filter
  const renderLicenseFilter = (props: {
    filterText: string
    onFilterChange: (e: React.ChangeEvent<HTMLInputElement>) => void
  }) => <AllowedLicensesFilter filterText={props.filterText} onFilterChange={props.onFilterChange} />

  // TODO: Use a unique key for each license item, otherwise item selection will glitch.
  const getLicenseKey = (license: LicenseEntry): string => {
    return `${license.level}-${license.spdx_id}`
  }

  const canDelete = (license: LicenseEntry): boolean => {
    // Enterprise level UI does not support deleting items directly at the row level
    if (level === PolicyLevel.Enterprise) return false
    if (!canManagePolicy) return false
    return license.level === level
  }

  const onDelete = (spdxID: string) => {
    setItemsToDelete({spdxIds: [spdxID], isBulk: false})
  }

  const handleDeleteConfirm = () => {
    if (itemsToDelete) {
      deleteAllowedLicensesMutation?.mutate({
        spdxIds: itemsToDelete.spdxIds,
        ...(itemsToDelete.isBulk && {context: 'distributed'}),
      })
    }
    // Clear selection after delete confirmation
    clearSelectionCallback?.()
    setClearSelectionCallback(null)
    setItemsToDelete(null)
  }

  const handleDeleteCancel = () => {
    setClearSelectionCallback(null)
    setItemsToDelete(null)
  }

  const onBulkDelete =
    level === PolicyLevel.Enterprise && canManagePolicy
      ? (selectedLicenses: LicenseEntry[], clearSelection: () => void) => {
          setItemsToDelete({
            spdxIds: selectedLicenses.map(license => license.spdx_id),
            isBulk: true,
          })
          setClearSelectionCallback(() => clearSelection)
        }
      : undefined

  const errorMessage = deleteAllowedLicensesMutation?.error
    ? {
        title: 'Bulk delete allowed license error',
        description: deleteAllowedLicensesMutation.error.message || 'Failed to delete licenses. Please try again.',
      }
    : undefined

  return (
    <>
      <BaseList
        title="Allowed Licenses List"
        items={licenses}
        singleItemName="license"
        pluralItemName="licenses"
        zeroItemsHeading="Manage allowed licenses"
        zeroItemsDescription="Select which licenses on your dependencies can be used without review"
        zeroItemsIcon={<LawIcon size="medium" />}
        zeroItemsFilterHeading="No licenses match your filter"
        filterFunction={filterLicenses}
        sortFunction={sortLicenses}
        renderFilter={renderLicenseFilter}
        renderItem={renderLicenseItem}
        getItemKey={getLicenseKey}
        testId="allowed-licenses-list"
        onBulkDelete={onBulkDelete}
        errorMessage={errorMessage}
      />
      <LicensePolicyDeleteDialog
        isOpen={itemsToDelete !== null}
        onClose={handleDeleteCancel}
        onConfirm={handleDeleteConfirm}
        policyLevel={level}
        itemType={ItemType.License}
        itemName={itemsToDelete?.spdxIds.length === 1 ? itemsToDelete.spdxIds[0] : undefined}
      />
    </>
  )
}
