import {BaseListFilter} from '../BaseListView/BaseListFilter'

export function AllowedLicensesFilter({
  filterText,
  onFilterChange,
}: {
  filterText: string
  onFilterChange: (e: React.ChangeEvent<HTMLInputElement>) => void
}) {
  return (
    <BaseListFilter filterText={filterText} onFilterChange={onFilterChange} aria-label="Search or filter licenses" />
  )
}
